class Counter161 {
    var current: Int by Delegates.observable(26) { _, _, new -> println(new) }

    suspend fun advance(): Int {
        try {
            current += 1
        } catch (failure: IllegalStateException) {
            current = 0
        } finally {
            println("advanced")
        }
        return current
    }
}
sealed class Outcome162 {
    data class Success(val payload: String) : Outcome162()
    data object Failure : Outcome162()
}

fun describe162(outcome: Outcome162): String = when (outcome) {
    is Outcome162.Success -> outcome.payload
    Outcome162.Failure -> "failed"
}
